  <Compile Include="/travail/Atm/CashMachine.cs" /></ItemGroup>
</Project>
EOF
sed 's/class CashMachine(/class OldCashMachine(/' /tmp/CashMachine.orig.cs > Old.cs
cat > Program.cs <<'EOF'
using Atm;
sealed class Rec(IMoneyDispenser inner, int failAt, bool failLoad) : IMoneyDispenser {
  public List<string> Log = []; int n;
  public NoteCounts Stock => inner.Stock; public Denomination? Jammed => inner.Jammed;
  public bool Dispense(NoteCounts x){ Log.Add("D"+x); n++; return n!=failAt && inner.Dispense(x);}
  public bool Load(NoteCounts x){ Log.Add("L"+x); return !failLoad && inner.Load(x);}
}
static class P { static void Main(){
  Denomination?[] jams=[null,Denomination.Fifty,Denomination.Twenty,Denomination.Ten];
  var ops = new List<Operation>();
  for (var a=-20;a<=260;a+=5) ops.Add(new Operation.Withdraw(a));
  for (var f=-1;f<=2;f++) for (var t=-1;t<=2;t++) for (var n=-1;n<=2;n++) ops.Add(new Operation.Deposit(new(f,t,n)));
  long count=0, bad=0;
  for (var f=-1;f<=6;f++) for (var t=-1;t<=6;t++) for (var n=-1;n<=6;n++)
  foreach (var j in jams) foreach (var op in ops)
  foreach (var acc in new AccountState[]{new(250,0),new(100,50),new(0,0),new(255,-10),new(120,100)})
  for (var fail=0; fail<=3; fail++) foreach (var fl in new[]{false,true}) {
    var s=new NoteCounts(f,t,n);
    var d1=new Rec(new MoneyDispenser(s,j),fail,fl); var d2=new Rec(new MoneyDispenser(s,j),fail,fl);
    var r1=new OldCashMachine(d1).Execute(acc,op); var r2=new CashMachine(d2).Execute(acc,op);
    count++;
    if (r1!=r2 || !d1.Log.SequenceEqual(d2.Log) || d1.Stock!=d2.Stock) { if (bad++<5) Console.WriteLine($"{s} {j} {op} {acc} {fail} {fl}: {r1} vs {r2}"); }
  }
  Console.WriteLine($"{count} cas, {bad} différences");
}}
EOF
